insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('SG:early-childhood-teacher','2026-08-11',0,0,0,0,12,0,0,0,1,13,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 maps Preschool education teacher directly to 36100.','entry_level_basis','ECDA-recognised early-childhood training is the regulated preparation route. One reviewed university programme is retained as a direct academic pathway, but ECDA notes that a degree alone is not the basic certification qualification.','qualification_note','ECDA states that educators in Singapore kindergartens and childcare centres must meet the relevant professional, academic and language requirements and obtain educator certification for the age group they teach.','market_scope','Certification and programme availability are not treated as labour-demand evidence; shortage, vacancy, salary and growth remain unscored.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:primary-school-teacher','2026-08-11',0,0,0,0,10,0,0,0,4,14,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 maps Primary school teacher directly to 23500.','entry_level_basis','MOE school teaching uses structured teacher-selection and NIE professional preparation pathways, including education degrees and subject-specific diploma routes. No approved SG programme mapping is currently attached to this canonical profile.','qualification_note','MOE appointment and teacher-training requirements are employer and school-system entry requirements rather than one universal statutory personal occupational licence applying to every primary-school teacher in Singapore.','market_scope','Teacher training evidence is not converted into shortage, vacancy, earnings or growth credit in the foundation phase.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:secondary-school-teacher','2026-08-11',0,0,0,0,10,0,0,0,4,14,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 maps Secondary school teacher directly to 23400 and keeps junior-college/pre-university teaching separately at 23200.','entry_level_basis','MOE secondary-school teaching commonly requires subject expertise plus professional teacher preparation through NIE or another accepted appointment pathway. No approved SG programme mapping is currently attached to this canonical profile.','qualification_note','The public-school selection and professional-preparation pathway does not constitute a universal occupational licensing register for every secondary-school teacher across all Singapore employers.','market_scope','No exact recurring occupation-level market inputs are scored in SG v1.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:special-education-teacher','2026-08-11',0,0,0,0,10,0,0,0,4,14,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','Special Education Teacher is a deliberate umbrella across SSOC 23621 Teacher of the visually impaired, 23622 Early intervention teacher for infants and children and 23629 Special education teacher n.e.c.','entry_level_basis','SPED teaching requires disability- and learner-specific professional preparation and employer training. MOE and social-service-agency SPED schools operate within the National SPED Curriculum, but no approved canonical SG programme link is currently present.','qualification_note','There is no one universal statutory personal Special Education Teacher licence covering all three SSOC scopes. ECDA certification can apply when work falls within regulated preschool educator deployment, while SPED-school appointment and training requirements apply separately.','market_scope','The three distinct SPED scopes are not merged into a fabricated exact labour-market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:social-worker','2026-08-11',0,0,0,0,10,0,0,0,4,14,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','The broad canonical Social Worker spans SSOC 26621 Social worker (general), 26622 Medical social worker and 26629 Social work professional n.e.c.; Youth work professional 26623 is kept in the separate Youth Worker profile.','entry_level_basis','Recognised social-work degrees or graduate diplomas are the core professional preparation. Two approved Singapore Social Work programmes are retained as direct pathways.','qualification_note','Singapore has an MSF-owned, SWAAB-overseen professional accreditation system, but current SASW accreditation guidance explicitly states that accreditation is not mandatory. Employer and sector standards may nevertheless require or strongly prefer recognised social-work qualifications and accreditation.','market_scope','General, medical and other social-work professional scopes are preserved separately and market components remain unscored.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:youth-worker','2026-08-11',0,0,0,0,12,0,0,0,5,17,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 provides the direct professional occupation 26623 Youth work professional. The lower-level 34121 Youth work associate is retained as a related reference but not rolled into the primary professional code.','entry_level_basis','Youth work draws on social work, psychology, counselling and community-service preparation; five approved Singapore programmes are retained as related academic pathways.','qualification_note','There is no universal statutory Youth Worker occupational registration. Safeguarding, screening, employer training and role-specific requirements can apply when working with children, vulnerable young people or residential services.','market_scope','Professional and associate youth-work codes are not collapsed into one unsupported market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:community-worker','2026-08-11',0,0,0,0,15,0,0,0,5,20,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 has no exact five-digit occupation titled Community Worker. CampCareer keeps 34122 Social work associate as the closest practical support reference and 26629 Social work professional n.e.c. as a separate professional community-development reference rather than inventing one exact code.','entry_level_basis','Community work can be entered through social-service, community-development or related study and supervised practice. Three approved Singapore programmes are retained as related pathways.','qualification_note','There is no universal statutory Community Worker licence. Employers can impose safeguarding, casework, programme-delivery, volunteer-management or client-group-specific competency requirements.','market_scope','Associate and professional community-work references remain separate and no exact labour-market series is fabricated.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:counsellor','2026-08-11',0,0,0,0,10,0,0,0,4,14,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','The neutral Counsellor career spans SSOC 26631 rehabilitation, 26632 drugs/alcohol, 26633 family, 26634 school and 26639 counselling professional n.e.c. rather than one exact five-digit code.','entry_level_basis','NCSS describes postgraduate counselling qualifications as the international professional benchmark. The three currently approved Singapore psychology programmes are retained only as related study pathways, not as direct counselling qualifications.','qualification_note','NCSS states that Singapore does not require counsellors to be licensed. Singapore Association for Counselling registration is a professional credential with its own postgraduate and practice requirements, not a universal statutory occupational licence.','market_scope','Counselling specialisations are not aggregated into unsupported exact salary, vacancy or shortage figures at foundation stage.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11')
